If(
    gblUserLanguage = "ja-JP",
    With(
        {
            locWorkItemCreatedOn: LookUp(
                'Project Work Items',
                'Project Work item' = locSelectedWorkItem.'Project Work item'
            ).'Created On'
        },
        With(
            {
                varDefault: "Created on",
                varOOBTextId: "lblEditWorkItemCreatedOn1__locText"
            },
            With(
                {
                    varLocalizedText: LookUp(
                        colLocalization,
                        OOBTextID = varOOBTextId,
                        LocalizedText
                    )
                },
                Coalesce(
                    varLocalizedText,
                    varDefault
                )
            )
        ) & " " & Text(
            locWorkItemCreatedOn,
            "[$-en-US]dd mmm",
            gblUserLanguage
        )
    ),
    With(
        {
            locWorkItemCreatedOn: LookUp(
                'Project Work Items',
                'Project Work item' = locSelectedWorkItem.'Project Work item'
            ).'Created On'
        },
        If(
            DateDiff(
                Coalesce(
                    locWorkItemCreatedOn,
                    Now()
                ),
                Now(),
                Days
            ) = 0,
            With(
                {
                    varDefault: "Created at",
                    varOOBTextId: "lblEditWorkItemCreatedOn2__locText"
                },
                With(
                    {
                        varLocalizedText: LookUp(
                            colLocalization,
                            OOBTextID = varOOBTextId,
                            LocalizedText
                        )
                    },
                    Coalesce(
                        varLocalizedText,
                        varDefault
                    )
                )
            ) & " " & Text(
                TimeValue(
                    Coalesce(
                        Text(locWorkItemCreatedOn),
                        Text(Now())
                    )
                ),
                "[$-en-US]hh:mm AM/PM",
                gblUserLanguage
            ),
            With(
                {
                    varDefault: "Created on",
                    varOOBTextId: "lblEditWorkItemCreatedOn1__locText"
                },
                With(
                    {
                        varLocalizedText: LookUp(
                            colLocalization,
                            OOBTextID = varOOBTextId,
                            LocalizedText
                        )
                    },
                    Coalesce(
                        varLocalizedText,
                        varDefault
                    )
                )
            ) & " " & Text(
                locWorkItemCreatedOn,
                "[$-en-US]dd mmm",
                gblUserLanguage
            )
        )
    )
)

// This formula checks a few different scenarios where the SharePoint URL may be incorrect
With(
    {varSharePointUrl: txtSetupSharePoint_URL.Text},
    With(
        {
            varError_ValidUrl: IsMatch(
                varSharePointUrl,
                "^(http:\/\/www\.|https:\/\/www\.|http:\/\/|https:\/\/)?[a-z0-9]+([\-\.]{1}[a-z0-9]+)*\.[a-z]{2,5}(:[0-9]{1,5})?(\/.*)?$"
            ),
            varError_UrlSlashes: CountRows(
                MatchAll(
                    varSharePointUrl,
                    "\/"
                )
            ) = 4,
            varError_SharePointDotCom: !IsBlankOrError(
                Find(
                    ".sharepoint.com/sites/",
                    varSharePointUrl
                )
            ),
            varError_SiteName: !IsBlankOrError(
                Right(
                    varSharePointUrl,
                    Len(varSharePointUrl) - (Find(
                        ".sharepoint.com/sites/",
                        varSharePointUrl
                    ) + 23)
                )
            )
        },
        If(
            !IsBlank(varSharePointUrl),
            If(
                !varError_ValidUrl,
                "Please enter a valid URL",
                !varError_UrlSlashes,
                "URL must have exactly 4 forward slashes, like https://contoso.sharepoint.com/sites/TeamName",
                !varError_SharePointDotCom,
                "URL must include .sharepoint.com/sites/",
                !varError_SiteName,
                "URL must include at least a three character site name",
                Blank()
            ),
            Blank()
        )
    )
)
